<?php
require_once __DIR__.'/../config.php';require_admin();$pageTitle='Usage reports';
$stats=['downloads'=>(int)$pdo->query('SELECT COUNT(*) FROM downloads')->fetchColumn(),'ratings'=>(int)$pdo->query('SELECT COUNT(*) FROM resource_ratings')->fetchColumn(),'comments'=>(int)$pdo->query("SELECT COUNT(*) FROM resource_comments WHERE status='visible'")->fetchColumn(),'sessions'=>(int)$pdo->query('SELECT COUNT(*) FROM study_sessions')->fetchColumn()];
$popular=$pdo->query("SELECT r.id,r.title,s.name subject_name,COUNT(d.id) download_count FROM resources r JOIN subjects s ON s.id=r.subject_id LEFT JOIN downloads d ON d.resource_id=r.id WHERE r.status='approved' GROUP BY r.id ORDER BY download_count DESC,r.created_at DESC LIMIT 10")->fetchAll();
$monthly=$pdo->query("SELECT DATE_FORMAT(downloaded_at,'%Y-%m') month,COUNT(*) downloads FROM downloads GROUP BY DATE_FORMAT(downloaded_at,'%Y-%m') ORDER BY month DESC LIMIT 12")->fetchAll();require __DIR__.'/../includes/admin_header.php';?>
<div class="metric-grid"><div class="metric"><strong><?= $stats['downloads'] ?></strong><span>Total downloads</span></div><div class="metric"><strong><?= $stats['ratings'] ?></strong><span>Resource ratings</span></div><div class="metric"><strong><?= $stats['comments'] ?></strong><span>Visible comments</span></div><div class="metric"><strong><?= $stats['sessions'] ?></strong><span>Study sessions scheduled</span></div></div>
<section class="panel mb-2"><h2>Most downloaded resources</h2><p>Download counts help identify useful study materials.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Resource</th><th>Subject</th><th>Downloads</th></tr></thead><tbody><?php foreach($popular as $p): ?><tr><td><?= e($p['title']) ?></td><td><?= e($p['subject_name']) ?></td><td><?= (int)$p['download_count'] ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel"><h2>Downloads by month</h2><?php if($monthly): ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Month</th><th>Downloads</th></tr></thead><tbody><?php foreach($monthly as $m): ?><tr><td><?= e($m['month']) ?></td><td><?= (int)$m['downloads'] ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p>No download activity recorded yet. Activity will appear here once students download resources.</p><?php endif; ?></section>
<?php require __DIR__.'/../includes/admin_footer.php';?>
